import{_ as t,o as r,c as a,a5 as s}from"./chunks/framework.BmD0ICqc.js";const i="/study/images/browser/csrf-request-flow.svg",o="/study/images/browser/csrf-validation-flow.svg",f=JSON.parse('{"title":"CSRFとリクエスト検証 — Cookie付きの要求を受理する条件","description":"","frontmatter":{"title":"CSRFとリクエスト検証 — Cookie付きの要求を受理する条件","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"ブラウザがCookieを付けて別オリジンへフォームを送る経路と、サーバーがOriginやCSRFトークンで状態変更を検証する手順を説明する。","aliases":["CSRF","Cross-Site Request Forgery","クロスサイトリクエストフォージェリ","リクエスト偽造","ambient authority","Origin","Referer","SameSite","synchronizer token","CSRFトークン","CORS","preflight"],"verification":"WHATWG標準、RFC 9110、CookieのIETF改訂草案、OWASP資料と照合（2026-11-05）"}},"headers":[],"relativePath":"browser/csrf-and-request-validation.md","filePath":"browser/csrf-and-request-validation.md"}'),h={name:"browser/csrf-and-request-validation.md"};function n(l,e,c,p,d,g){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="csrfとリクエスト検証-—-cookie付きの要求を受理する条件" tabindex="-1">CSRFとリクエスト検証 — Cookie付きの要求を受理する条件 <a class="header-anchor" href="#csrfとリクエスト検証-—-cookie付きの要求を受理する条件" aria-label="Permalink to &quot;CSRFとリクエスト検証 — Cookie付きの要求を受理する条件&quot;">​</a></h1><p><strong>CSRF</strong>（Cross-Site Request Forgery）は、攻撃者が利用者のブラウザに要求を送らせ、ログイン中のサイトなどで意図しない操作を行わせる攻撃です。たとえば別のページが設定変更先へフォームを送信し、ブラウザが対象サイトのセッションCookieを付けるとします。サーバーがセッションの有効性だけで更新を受理すれば、その利用者の設定が変更されます。サーバーが確認するべきなのは、Cookieに対応する利用者に加え、その操作をどの文脈で受理するかです。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#introduction" target="_blank" rel="noreferrer">OWASPのCSRF対策</a>、<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a></p><h2 id="フォームの送信にcookieが付くまで" tabindex="-1">フォームの送信にCookieが付くまで <a class="header-anchor" href="#フォームの送信にcookieが付くまで" aria-label="Permalink to &quot;フォームの送信にCookieが付くまで&quot;">​</a></h2><p>HTMLのフォームは、<code>action</code> に別オリジンのURLを指定して送信できます。ブラウザはその宛先、要求の文脈、Cookieの属性などを照合し、条件に合うCookieを要求に付けます。フォームを作ったページがCookieの値を知っている必要はありません。このように宛先に応じて自動的に使われる資格情報を、<strong>ambient authority</strong> と呼びます。<a href="https://html.spec.whatwg.org/multipage/form-control-infrastructure.html#form-submission-algorithm" target="_blank" rel="noreferrer">WHATWG HTMLのフォーム送信</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-8.2" target="_blank" rel="noreferrer">IETF Cookie改訂草案のambient authority</a></p><p>たとえば、<code>https://account.example.test</code> がアカウント設定を持ち、<code>https://community.example.test</code> が利用者のコンテンツを表示できる別のページだとします。両者は別オリジンですが同一サイトです。利用者がコミュニティ側のフォームから設定のURLへ送信すると、条件を満たす場合は次のような要求がアカウント側に届きます。<a href="https://html.spec.whatwg.org/multipage/browsers.html#sites" target="_blank" rel="noreferrer">WHATWG HTMLのオリジンとサイト</a>、<a href="https://fetch.spec.whatwg.org/#origin-header" target="_blank" rel="noreferrer">WHATWG FetchのOriginヘッダー</a></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /settings/theme </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> account.example.test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Origin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://community.example.test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cookie</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sid=example-session-id</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/x-www-form-urlencoded</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Length</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">theme=dark</span></span></code></pre></div><p>この例では <code>Origin</code> がフォームを送ったページのオリジンを示し、Cookieの選択先はアカウント側です。セッションCookieをアカウント側だけのhost-onlyにしていても、アカウント側へ向かう要求には付き得ます。送信と応答の読み取りも別の段階です。元のページが別オリジンの応答の内容を読めなくても、更新の結果はサーバー側に残り得ます。<a href="https://fetch.spec.whatwg.org/#http-cors-protocol" target="_blank" rel="noreferrer">WHATWG FetchのCORSプロトコル</a>、<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a></p><figure class="study-figure"><img src="`+i+'" alt="アカウントサイトのセッションCookieを持つブラウザが、別オリジンのコミュニティからアカウントサイトへフォームを送る。ブラウザが宛先に合うCookieを付けるため、セッションだけを検証するサーバーでは設定が変更される場合がある。" width="760" height="1120" loading="lazy"><figcaption>フォームが送る値、ブラウザが付ける資格情報、サーバーが更新を受理する判断を順番に追います。<a href="/study/images/browser/csrf-request-flow.svg" target="_blank" rel="noopener noreferrer">Cookie付きの要求の流れを拡大</a></figcaption></figure><h2 id="samesiteとオリジンの違い" tabindex="-1">SameSiteとオリジンの違い <a class="header-anchor" href="#samesiteとオリジンの違い" aria-label="Permalink to &quot;SameSiteとオリジンの違い&quot;">​</a></h2><p><code>SameSite</code> はサイトを単位にCookieの送信条件を絞ります。たとえば明示的な <code>Lax</code> は、別サイトからのトップレベル移動でも、GETなどHTTPのsafeメソッドなら送信を許す場合があります。<code>Strict</code> の条件はより狭く、同一サイトの文脈が必要です。埋め込みページでは祖先の文書も同一サイトかどうかの判断に関わります。<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-4.1.2.7" target="_blank" rel="noreferrer">IETF Cookie改訂草案のSameSite</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-5.2" target="_blank" rel="noreferrer">同一サイトの判定</a></p><p>オリジンはスキーム、ホスト、ポートの組で決まります。通常のHTTP(S)ページでは、スキームとサイトの単位が同じでも、ホストやポートが違えば別オリジンになり得ます。たとえば同じループバックIPとスキームを使う二つのポートは同一サイトで、フォームを送るページと受けるページのオリジンは異なります。Cookieのホスト照合にもポートの区別がありません。ローカル実験では、この関係を使って、<code>SameSite=Strict</code> でも条件に合う別オリジンのフォーム送信にCookieが付くことを観察します。<a href="https://html.spec.whatwg.org/multipage/browsers.html#concept-origin" target="_blank" rel="noreferrer">WHATWG HTMLのオリジン</a>、<a href="https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis-22#section-8.5" target="_blank" rel="noreferrer">IETF Cookie改訂草案の分離の限界</a></p><h2 id="状態変更の入口を分ける" tabindex="-1">状態変更の入口を分ける <a class="header-anchor" href="#状態変更の入口を分ける" aria-label="Permalink to &quot;状態変更の入口を分ける&quot;">​</a></h2><p>HTTPでGETやHEADなどがsafeとされるのは、利用者がリソースの状態変更を要求する用途を想定しないためです。たとえば <code>GET /settings/theme</code> は現在の設定の取得に使い、保存はPOSTやPATCHなどの専用の経路に分けます。リンクを開くことやプリフェッチが状態変更につながる設計では、GETでCookieが付く条件がそのまま攻撃経路になり得ます。変更用の経路では、メソッドと認証・認可に加えてCSRFの検証を行います。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-9.2.1" target="_blank" rel="noreferrer">RFC 9110のSafe Methods</a>、<a href="/study/network/http-messages.html">HTTPメッセージ</a></p><h2 id="送信元のオリジンを確認する" tabindex="-1">送信元のオリジンを確認する <a class="header-anchor" href="#送信元のオリジンを確認する" aria-label="Permalink to &quot;送信元のオリジンを確認する&quot;">​</a></h2><p>変更を受け付けるサーバーでは、ブラウザが送った <code>Origin</code> を、アプリで定めた許可オリジンと正確に照合できます。比較するのはスキーム、ホスト、有効なポートの組です。たとえば <code>https://account.example.test</code> を許可する場合、単純な文字列の前方一致では <code>https://account.example.test.other.test</code> のような別ホストも通ってしまいます。期待するオリジンはアプリの設定から取り、リバースプロキシがある場合は、信頼するプロキシが確定した転送情報だけを使います。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#using-standard-headers-to-verify-origin" target="_blank" rel="noreferrer">OWASPの送信元検証</a>、<a href="https://html.spec.whatwg.org/multipage/browsers.html#concept-origin" target="_blank" rel="noreferrer">WHATWG HTMLのオリジン</a></p><p>ブラウザや要求の種類によっては <code>Origin</code> が付かない場合があります。互換性のために <code>Referer</code> を使う構成では、<code>Origin</code> が欠けたときだけ参照元URLを解析し、そのオリジンを同じ規則で照合します。参照元もプライバシー方針などで省略され得ます。<code>Origin: null</code> は不透明なオリジンなどで使われる値です。許可オリジンと一致する値を確認できないときに更新を拒否する方針なら、<code>null</code>、不正な値、検証できるヘッダーがない場合も拒否に含めます。<a href="https://fetch.spec.whatwg.org/#origin-header" target="_blank" rel="noreferrer">WHATWG FetchのOriginヘッダー</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#using-standard-headers-to-verify-origin" target="_blank" rel="noreferrer">OWASPの送信元検証</a></p><p>ブラウザは、ページのJavaScriptから <code>Origin</code> を任意の値に書き換えることを制限します。ブラウザ外のHTTPクライアントは任意の値を送れるため、利用者の認証と認可はセッションなどを使って確認します。<a href="https://fetch.spec.whatwg.org/#forbidden-request-header" target="_blank" rel="noreferrer">WHATWG Fetchの禁止された要求ヘッダー</a></p><h2 id="セッションに結び付いたトークンを照合する" tabindex="-1">セッションに結び付いたトークンを照合する <a class="header-anchor" href="#セッションに結び付いたトークンを照合する" aria-label="Permalink to &quot;セッションに結び付いたトークンを照合する&quot;">​</a></h2><p>サーバー側にセッションがある構成では、<strong>同期トークン方式</strong>（synchronizer token pattern）が使えます。サーバーは暗号学的に安全な乱数で推測しにくい値を作り、セッションに結び付けます。正規のフォームにはその値を隠しフィールドとして含めます。フォーム送信時に、サーバーは受け取った値を該当セッションの値と照合し、欠落や不一致があれば更新を拒否します。Cookieはブラウザが自動で送りますが、フォームのフィールドは送信元のページが内容を用意する必要があります。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#synchronizer-token-pattern" target="_blank" rel="noreferrer">OWASPの同期トークン方式</a></p><p>フォームなら要求本文、JavaScriptのAPI呼び出しなら要求ヘッダーなどでトークンを渡します。URLに置くとアクセスログ、履歴、条件によっては <code>Referer</code> に残るため、本文やヘッダーを使います。この方式ではサーバーが持つトークンを照合し、Cookieの存在はセッションの確認に使います。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#transmitting-csrf-tokens-in-synchronized-patterns" target="_blank" rel="noreferrer">OWASPのトークンの受け渡し</a></p><figure class="study-figure"><img src="'+o+'" alt="状態変更を受けるサーバーがメソッド、セッションと権限、送信元のオリジン、セッションに結び付いたCSRFトークンを検証する。条件を満たした場合に更新し、検証に失敗した場合は変更を拒否する。" width="760" height="1220" loading="lazy"><figcaption>送信元とトークンを併用する構成の例です。更新は必要な検証が通ってから行います。<a href="/study/images/browser/csrf-validation-flow.svg" target="_blank" rel="noopener noreferrer">状態変更の検証手順を拡大</a></figcaption></figure><h2 id="javascriptのapiとcorsの境界" tabindex="-1">JavaScriptのAPIとCORSの境界 <a class="header-anchor" href="#javascriptのapiとcorsの境界" aria-label="Permalink to &quot;JavaScriptのAPIとCORSの境界&quot;">​</a></h2><p>APIが <code>X-CSRF-Token</code> のような独自の要求ヘッダーを必須にすると、変更をヘッダー付きの呼び出しに絞れます。通常のHTMLフォームから指定できるのは、宛先やメソッド、送るフィールドなどです。別オリジンのJavaScriptが独自ヘッダーを付けて <code>fetch()</code> する場合は、ブラウザが必要に応じてpreflightのOPTIONSを送り、API側のCORS方針が許可した場合に本要求を送ります。API側ではヘッダーが必要なルートに確実に適用し、資格情報付きのCORSを使う場合は信頼するオリジンを明示します。信頼しないオリジンにもpreflightを許可すると、この境界は緩みます。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#custom-headers-and-cors" target="_blank" rel="noreferrer">OWASPのカスタムヘッダーとCORS</a>、<a href="https://fetch.spec.whatwg.org/#cors-preflight-fetch" target="_blank" rel="noreferrer">WHATWG Fetchのpreflight</a></p><p>通常のURLエンコードされたフォームPOSTは、カスタムヘッダー付きのCORS要求とは異なる経路で送れます。CORSで応答を公開しない設定だけでフォーム経由の状態変更を防ぐことはできません。フォームとJavaScriptの両方を受けるAPIでは、どの経路にも状態変更前の検証がかかることを確かめます。<a href="https://html.spec.whatwg.org/multipage/form-control-infrastructure.html#form-submission-algorithm" target="_blank" rel="noreferrer">WHATWG HTMLのフォーム送信</a>、<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a></p><h2 id="xssとの違いと組み合わせる防御" tabindex="-1">XSSとの違いと組み合わせる防御 <a class="header-anchor" href="#xssとの違いと組み合わせる防御" aria-label="Permalink to &quot;XSSとの違いと組み合わせる防御&quot;">​</a></h2><p>CSRFは別ページなどからブラウザに対象サイトへの要求を送らせます。XSSでは攻撃者のコードが対象サイトのページの中で動きます。その場合は正規ページと同じオリジンから要求を送り、ページに置かれたトークンを読み取れることがあります。Cookieの送信範囲、変更用のメソッド、送信元の検証やトークン、XSSを防ぐ出力処理は、それぞれ異なる経路を受け持ちます。<a href="/study/browser/xss-and-csp.html">XSSとCSP</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html#introduction" target="_blank" rel="noreferrer">OWASPのCSRF対策</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>公開版は、フォーム、Cookie、送信元、トークンの条件と、サーバーでの受理・拒否をたどるシミュレーションです。ローカル版では、別ポートの二つの教材オリジンでブラウザのフォームPOSTを実際に送ります。この二つを実験範囲として、CSRFの追加検査を行わないルート、アプリのオリジンと照合するルート、同期トークンのルートを比べます。<a href="/study/practice/browser/csrf-observation.html">CSRFで要求の送信と検証を観察する</a></p>',28)])])}const m=t(h,[["render",n]]);export{f as __pageData,m as default};
